CREATE FUNCTION public.get_auth_user_by_email(p_email text) RETURNS TABLE(id uuid, email text, raw_user_meta_data jsonb, created_at timestamp with time zone, last_sign_in_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
