CREATE FUNCTION public.enqueue_sync_job(p_tenant_id uuid, p_catalog_item_id uuid, p_target text DEFAULT 'both'::text, p_operation text DEFAULT 'upsert'::text) RETURNS uuid
    LANGUAGE plpgsql
