-- @seq 439
CREATE FUNCTION public.get_pending_sync_jobs(p_limit integer DEFAULT 100) RETURNS TABLE(id uuid, tenant_id uuid, catalog_item_id uuid, target text, operation text, attempts integer)
    LANGUAGE plpgsql
    AS $$
