 ('social_platform','Social platform','business_model','User-generated content with trust & safety and ad center.', '{social_platform,social_trust_safety,ad_center,social_sync}', '{}'),
 ('healthcare','Healthcare','industry','Patients (MRN), providers (NPI), visits; PHI controls. Needs a HIPAA deployment.', '{healthcare,tracked_records,appointments}', '{hipaa}'),
 ('financial_services','Financial services','industry','Policies (policy numbers), claims history, policyholders and beneficiaries.', '{financial_services,tracked_records,deals,pipelines}', '{}'),
 ('real_estate','Real estate','industry','Properties (MLS #, address, listing status), showings, buyer and listing pipelines.', '{real_estate,tracked_records,deals,pipelines,calendar}', '{}'),
 ('auto_dealer','Auto dealer','industry','Vehicles (validated VIN), service records, recalls, vehicle sales pipeline.', '{auto_dealer,tracked_records,deals,pipelines,appointments}', '{}'),
 ('edtech','EdTech','industry','Students (student ID), enrollment history, guardians, admissions pipeline.', '{edtech,tracked_records,deals,pipelines}', '{}')
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, description = EXCLUDED.description, modules = EXCLUDED.modules,
  requires_compliance = EXCLUDED.requires_compliance, updated_at = now();

CREATE TABLE IF NOT EXISTS public.platform_picklist_values (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id  uuid REFERENCES public.tenants(id) ON DELETE CASCADE,   -- NULL = available to every tenant
  list_code  text NOT NULL,
  value      text NOT NULL,
  label      text NOT NULL,
  sort_order integer NOT NULL DEFAULT 100,
  pack_code  text,
  is_active  boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION public.platform_picklist_ok(p_tenant uuid, p_list text, p_value text) RETURNS boolean
LANGUAGE sql STABLE SET search_path = public, pg_catalog AS $$
  SELECT p_value IS NULL OR EXISTS (SELECT 1 FROM public.platform_picklist_values v
           WHERE v.list_code = p_list AND v.value = p_value AND v.is_active
             AND (v.tenant_id IS NULL OR v.tenant_id = p_tenant)) $$;

CREATE OR REPLACE FUNCTION public.platform__picklist_guard() RETURNS trigger
LANGUAGE plpgsql SET search_path = public, pg_catalog AS $$
DECLARE j jsonb := to_jsonb(NEW); v text := j ->> TG_ARGV[0]; t uuid := nullif(j ->> 'tenant_id', '')::uuid;
BEGIN
  IF TG_OP = 'UPDATE' AND v IS NOT DISTINCT FROM (to_jsonb(OLD) ->> TG_ARGV[0]) THEN RETURN NEW; END IF;
  IF NOT public.platform_picklist_ok(t, TG_ARGV[1], v) THEN
    RAISE EXCEPTION '%.% = % is not an allowed value; add it under Settings > Picklists (list %)',
      TG_TABLE_NAME, TG_ARGV[0], v, TG_ARGV[1] USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

CREATE TABLE IF NOT EXISTS public.platform_notification_preferences (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id   uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  user_id     uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  event_type  text NOT NULL DEFAULT '*',          -- '*' = default for every event
  channel     text NOT NULL CHECK (channel IN ('in_app','email','push','sms')),
  enabled     boolean NOT NULL DEFAULT true,
  digest      text NOT NULL DEFAULT 'instant' CHECK (digest IN ('instant','daily','weekly')),
  quiet_start time,
  quiet_end   time,
  timezone    text NOT NULL DEFAULT 'America/Chicago',
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, user_id, event_type, channel)
);

CREATE TABLE IF NOT EXISTS public.platform_outbox (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id      uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  channel        text NOT NULL,
  event_type     text NOT NULL,
  aggregate_type text,
  aggregate_ref  text,
  payload        jsonb NOT NULL DEFAULT '{}'::jsonb,
  status         text NOT NULL DEFAULT 'pending',
  attempts       integer NOT NULL DEFAULT 0,
  available_at   timestamptz NOT NULL DEFAULT now(),
  source_table   text,
  source_id      text,
  processed_at   timestamptz,
  last_error     text,
  created_at     timestamptz NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION public.platform_notify(
  p_tenant uuid, p_user uuid, p_event text, p_title text, p_body text DEFAULT NULL,
  p_url text DEFAULT NULL, p_priority text DEFAULT 'normal', p_ref_type text DEFAULT NULL, p_ref_id uuid DEFAULT NULL,
  p_force_channels text[] DEFAULT NULL)          -- pages use this: urgent alerts ignore quiet hours
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog AS $$
DECLARE v_id uuid; ch text; v_on boolean; p record; v_avail timestamptz; v_local time;
BEGIN
  IF p_user IS NULL THEN RETURN NULL; END IF;
  FOREACH ch IN ARRAY ARRAY['in_app','email','push','sms'] LOOP
    SELECT * INTO p FROM public.platform_notification_preferences n
     WHERE n.tenant_id = p_tenant AND n.user_id = p_user AND n.channel = ch AND n.event_type IN (p_event, '*')
     ORDER BY (n.event_type = p_event) DESC LIMIT 1;
    v_on := CASE WHEN p_force_channels IS NOT NULL THEN ch = ANY (p_force_channels)
                 WHEN p.id IS NOT NULL THEN p.enabled
                 ELSE ch = 'in_app' OR (ch = 'email' AND p_priority IN ('high','urgent')) END;
    CONTINUE WHEN NOT v_on;
    IF ch = 'in_app' THEN
      INSERT INTO public.user_notifications(tenant_id, user_id, notification_type, title, body, priority, action_url, metadata)
      VALUES (p_tenant, p_user, p_event, p_title, p_body, p_priority, p_url,
              jsonb_build_object('ref_type', p_ref_type, 'ref_id', p_ref_id))
      RETURNING id INTO v_id;
    ELSE
      v_avail := now();
      IF p.id IS NOT NULL AND p.quiet_start IS NOT NULL AND p.quiet_end IS NOT NULL AND p_force_channels IS NULL THEN
        v_local := (now() AT TIME ZONE p.timezone)::time;
        IF (p.quiet_start < p.quiet_end AND v_local >= p.quiet_start AND v_local < p.quiet_end)
           OR (p.quiet_start > p.quiet_end AND (v_local >= p.quiet_start OR v_local < p.quiet_end)) THEN
          v_avail := ((now() AT TIME ZONE p.timezone)::date + p.quiet_end
                      + CASE WHEN v_local >= p.quiet_end AND p.quiet_start > p.quiet_end THEN interval '1 day' ELSE interval '0' END)
                     AT TIME ZONE p.timezone;
        END IF;
      END IF;
      INSERT INTO public.platform_outbox(tenant_id, channel, event_type, aggregate_type, aggregate_ref, payload, status, attempts,
                                         available_at, source_table, source_id)
      VALUES (p_tenant, ch, 'notify.' || p_event, p_ref_type, p_ref_id::text,
              jsonb_build_object('user_id', p_user, 'title', p_title, 'body', p_body, 'url', p_url, 'priority', p_priority),
              'pending', 0, v_avail, 'platform_notify', gen_random_uuid()::text);
    END IF;
  END LOOP;
  RETURN v_id;
END $$;

CREATE TABLE IF NOT EXISTS public.platform_roles (
  code        text PRIMARY KEY,
  label       text NOT NULL,                 -- default label; packs rename via platform_terminology 'role.<code>'
  plural      text NOT NULL,
  rank        integer NOT NULL,              -- higher = more authority (used when one user holds several grants)
  role_kind   text NOT NULL CHECK (role_kind IN ('staff','participant','platform')),
  description text,
  sort_order  integer NOT NULL DEFAULT 100
);

CREATE TABLE IF NOT EXISTS public.platform_role_aliases (
  alias     text PRIMARY KEY,
  role_code text NOT NULL REFERENCES public.platform_roles(code) ON DELETE CASCADE,
  title     text,                         -- what the business called it
  source    text NOT NULL DEFAULT 'unify 06e'
);

CREATE TABLE IF NOT EXISTS public.platform_member_roles (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  user_id       uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  role_code     text NOT NULL REFERENCES public.platform_roles(code) ON UPDATE CASCADE,
  title         text,
  scope_type    text NOT NULL DEFAULT 'tenant' CHECK (scope_type IN ('tenant','location','team','program','cohort')),
  scope_id      uuid,                                           -- the location / team / program / cohort
  status        text NOT NULL DEFAULT 'active' CHECK (status IN ('active','revoked','expired')),
  assigned_by   uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  assigned_at   timestamptz NOT NULL DEFAULT now(),
  expires_at    timestamptz,
  revoked_at    timestamptz,
  revoked_by    uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  revoke_reason text,
  metadata      jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  CHECK ((scope_type = 'tenant') = (scope_id IS NULL))
);

CREATE OR REPLACE FUNCTION public.platform_resolve_role(p_role text) RETURNS text
LANGUAGE sql STABLE SET search_path = public, pg_catalog AS $$
  SELECT coalesce((SELECT code FROM public.platform_roles WHERE code = lower(btrim(p_role))),
                  (SELECT role_code FROM public.platform_role_aliases WHERE alias = lower(btrim(p_role)))) $$;

CREATE OR REPLACE FUNCTION public.platform__user_has_role(p_tenant uuid, p_user uuid, p_role text, p_scope_type text DEFAULT 'tenant', p_scope_id uuid DEFAULT NULL)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_catalog AS $$
  WITH want AS (SELECT r.rank, r.role_kind FROM public.platform_roles r WHERE r.code = public.platform_resolve_role(p_role))
  SELECT EXISTS (SELECT 1 FROM public.tenant_memberships tm JOIN public.platform_roles r ON r.code = tm.role, want w
                  WHERE tm.tenant_id = p_tenant AND tm.user_id = p_user AND tm.active AND tm.status = 'active'
                    AND w.role_kind = 'staff' AND r.rank >= w.rank)
      OR EXISTS (SELECT 1 FROM public.platform_member_roles g JOIN public.platform_roles r ON r.code = g.role_code, want w
                  WHERE g.tenant_id = p_tenant AND g.user_id = p_user AND g.status = 'active'
                    AND (g.expires_at IS NULL OR g.expires_at > now())
                    AND r.role_kind = w.role_kind AND r.rank >= w.rank
                    AND (g.scope_type = 'tenant' OR (g.scope_type = p_scope_type AND g.scope_id = p_scope_id))) $$;

CREATE OR REPLACE FUNCTION public.platform_has_role(p_tenant uuid, p_role text, p_scope_type text DEFAULT 'tenant', p_scope_id uuid DEFAULT NULL)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_catalog AS $$
  SELECT public.platform_is_admin() OR coalesce(public.platform__user_has_role(p_tenant, auth.uid(), p_role, p_scope_type, p_scope_id), false) $$;

-- ---------------------------------------------------------------------
-- 03_contacts_parties_crm/04_appointments.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- 04_appointments.sql — the missing Appointments domain, plus the other
-- parent tables that existing columns already point at but that were never
-- created:
--
--   crm_dependents               <- 23 dangling dependent_id columns (pet, child, vehicle, property ...)
--   crm_appointments             <- 14 dangling appointment_id columns; outbox_emit already has branches for it
--   crm_appointment_resources    rooms / stations / chairs / equipment
--   crm_appointment_status_history
--   crm_staff_blocked_times      canonical for legacy blocked_times (+ date-specific availability)
--   crm_booking_policies         notice, horizon, slot size, cancellation window, deposit, auto-confirm
--   commerce_register_sessions   <- 3 dangling register_session_id columns (POS)
--   platform_report_definitions  <- analytics_export_runs.definition_id
--
-- RPCs: crm_available_slots, crm_book_appointment, crm_reschedule_appointment,
--       crm_cancel_appointment, crm_set_appointment_status
-- Customer rollups kept current: next_appointment_at, last_visit_at, total_visits, no_show_rate.
-- Staff and resource double-booking is impossible (GiST exclusion constraints).
-- Idempotent.
-- =====================================================================
\set ON_ERROR_STOP on
CREATE EXTENSION IF NOT EXISTS btree_gist;
BEGIN;

-- ------------------------------------------------------------ dependents
CREATE TABLE IF NOT EXISTS public.crm_dependents (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id           uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  primary_customer_id uuid REFERENCES public.crm_customers(id) ON DELETE SET NULL,
  dependent_type      text NOT NULL DEFAULT 'person'
                      CHECK (dependent_type IN ('person','child','pet','vehicle','property','equipment','other')),
  name                text NOT NULL,
  date_of_birth       date,
  attributes          jsonb NOT NULL DEFAULT '{}'::jsonb,   -- species/breed/weight, make/model/VIN, address ...
  notes               text,
  photo_url           text,
  is_active           boolean NOT NULL DEFAULT true,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS crm_dependents_customer_idx ON public.crm_dependents(tenant_id, primary_customer_id);

-- ------------------------------------------------------------ resources
CREATE TABLE IF NOT EXISTS public.crm_appointment_resources (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  location_id   uuid REFERENCES public.locations(id) ON DELETE SET NULL,
  name          text NOT NULL,
  resource_type text NOT NULL DEFAULT 'station'
                CHECK (resource_type IN ('room','station','chair','table','equipment','vehicle','other')),
  capacity      integer NOT NULL DEFAULT 1 CHECK (capacity > 0),
  is_active     boolean NOT NULL DEFAULT true,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, location_id, name)
);

-- ------------------------------------------------------------ policies
CREATE TABLE IF NOT EXISTS public.crm_booking_policies (
  id                        uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id                 uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  location_id               uuid REFERENCES public.locations(id) ON DELETE CASCADE,
  service_id                uuid REFERENCES public.crm_services(id) ON DELETE CASCADE,
  slot_interval_minutes     integer NOT NULL DEFAULT 15 CHECK (slot_interval_minutes BETWEEN 5 AND 240),
  min_notice_minutes        integer NOT NULL DEFAULT 60 CHECK (min_notice_minutes >= 0),
  max_advance_days          integer NOT NULL DEFAULT 90 CHECK (max_advance_days > 0),
  buffer_before_minutes     integer NOT NULL DEFAULT 0 CHECK (buffer_before_minutes >= 0),
  buffer_after_minutes      integer NOT NULL DEFAULT 0 CHECK (buffer_after_minutes >= 0),
  cancellation_window_hours integer NOT NULL DEFAULT 24 CHECK (cancellation_window_hours >= 0),
  late_cancel_fee           numeric(12,2) NOT NULL DEFAULT 0,
  no_show_fee               numeric(12,2) NOT NULL DEFAULT 0,
  deposit_required          boolean NOT NULL DEFAULT false,
  deposit_amount            numeric(12,2),
  allow_online_booking      boolean NOT NULL DEFAULT true,
  auto_confirm              boolean NOT NULL DEFAULT true,
  default_timezone          text NOT NULL DEFAULT 'America/Chicago',
  created_at                timestamptz NOT NULL DEFAULT now(),
  updated_at                timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS crm_booking_policies_scope_uq
  ON public.crm_booking_policies(tenant_id, location_id, service_id) NULLS NOT DISTINCT;

-- ------------------------------------------------------------ appointments
CREATE TABLE IF NOT EXISTS public.crm_appointments (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id             uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  appointment_number    text NOT NULL,
  customer_id           uuid NOT NULL REFERENCES public.crm_customers(id) ON DELETE RESTRICT,
  dependent_id          uuid REFERENCES public.crm_dependents(id) ON DELETE SET NULL,
  location_id           uuid REFERENCES public.locations(id) ON DELETE SET NULL,
  staff_id              uuid REFERENCES public.crm_staff(id) ON DELETE SET NULL,
  resource_id           uuid REFERENCES public.crm_appointment_resources(id) ON DELETE SET NULL,
  service_id            uuid REFERENCES public.crm_services(id) ON DELETE SET NULL,
  status                text NOT NULL DEFAULT 'scheduled'
                        CHECK (status IN ('requested','scheduled','confirmed','checked_in','in_progress',
                                          'completed','cancelled','no_show','rescheduled')),
  starts_at             timestamptz NOT NULL,
  ends_at               timestamptz NOT NULL,
  buffer_before_minutes integer NOT NULL DEFAULT 0 CHECK (buffer_before_minutes >= 0),
  buffer_after_minutes  integer NOT NULL DEFAULT 0 CHECK (buffer_after_minutes >= 0),
  block_starts_at       timestamptz,          -- starts_at - buffer (maintained by trigger)
  block_ends_at         timestamptz,          -- ends_at + buffer
  timezone              text NOT NULL DEFAULT 'America/Chicago',
  source_channel        text NOT NULL DEFAULT 'staff'
                        CHECK (source_channel IN ('staff','online','phone','walk_in','portal','api','import')),
  customer_notes        text,
  internal_notes        text,
  cancellation_reason   text,
  cancelled_at          timestamptz,
  cancelled_by          uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  late_cancel           boolean NOT NULL DEFAULT false,
  confirmed_at          timestamptz,
  checked_in_at         timestamptz,
  started_at            timestamptz,
  completed_at          timestamptz,
  no_show_at            timestamptz,
  rescheduled_from_id   uuid REFERENCES public.crm_appointments(id) ON DELETE SET NULL,
  deposit_id            uuid REFERENCES public.commerce_deposits(id) ON DELETE SET NULL,
  estimate_id           uuid REFERENCES public.acct_estimates(id) ON DELETE SET NULL,
  invoice_id            uuid REFERENCES public.acct_ar_invoices(id) ON DELETE SET NULL,
  sale_id               uuid REFERENCES public.commerce_sales(id) ON DELETE SET NULL,
  erp_order_id          uuid REFERENCES public.erp_orders(id) ON DELETE SET NULL,
  estimated_total       numeric(12,2),
  idempotency_key       text,
  created_by            uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  metadata              jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT crm_appointments_time_ck CHECK (ends_at > starts_at),
  CONSTRAINT crm_appointments_number_uq UNIQUE (tenant_id, appointment_number),
  CONSTRAINT crm_appointments_idem_uq UNIQUE (tenant_id, idempotency_key),
  CONSTRAINT crm_appointments_no_staff_overlap EXCLUDE USING gist
    (staff_id WITH =, tstzrange(block_starts_at, block_ends_at, '[)') WITH &&)
    WHERE (staff_id IS NOT NULL AND status IN ('requested','scheduled','confirmed','checked_in','in_progress')),
  CONSTRAINT crm_appointments_no_resource_overlap EXCLUDE USING gist
    (resource_id WITH =, tstzrange(block_starts_at, block_ends_at, '[)') WITH &&)
    WHERE (resource_id IS NOT NULL AND status IN ('requested','scheduled','confirmed','checked_in','in_progress'))
);
CREATE INDEX IF NOT EXISTS crm_appointments_calendar_idx ON public.crm_appointments(tenant_id, starts_at);
CREATE INDEX IF NOT EXISTS crm_appointments_customer_idx ON public.crm_appointments(customer_id, starts_at DESC);
CREATE INDEX IF NOT EXISTS crm_appointments_staff_idx ON public.crm_appointments(staff_id, starts_at);

CREATE TABLE IF NOT EXISTS public.crm_appointment_status_history (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id      uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  appointment_id uuid NOT NULL REFERENCES public.crm_appointments(id) ON DELETE CASCADE,
  from_status    text,
  to_status      text NOT NULL,
  reason         text,
  changed_by     uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  changed_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS crm_appointment_status_history_appt_idx ON public.crm_appointment_status_history(appointment_id, changed_at);

CREATE TABLE IF NOT EXISTS public.crm_staff_blocked_times (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id   uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  staff_id    uuid REFERENCES public.crm_staff(id) ON DELETE CASCADE,       -- NULL = whole location/business closed
  location_id uuid REFERENCES public.locations(id) ON DELETE CASCADE,
  starts_at   timestamptz NOT NULL,
  ends_at     timestamptz NOT NULL,
  block_type  text NOT NULL DEFAULT 'blocked' CHECK (block_type IN ('blocked','time_off','holiday','break','extra_availability')),
  reason      text,
  legacy_source text,
  legacy_id   text,
  created_by  uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at  timestamptz NOT NULL DEFAULT now(),
  CHECK (ends_at > starts_at),
  UNIQUE (legacy_source, legacy_id)
);
CREATE INDEX IF NOT EXISTS crm_staff_blocked_times_idx ON public.crm_staff_blocked_times(tenant_id, staff_id, starts_at);

-- ------------------------------------------------------------ POS + reports
CREATE TABLE IF NOT EXISTS public.commerce_register_sessions (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id      uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  location_id    uuid REFERENCES public.locations(id) ON DELETE SET NULL,
  register_code  text NOT NULL DEFAULT 'main',
  status         text NOT NULL DEFAULT 'open' CHECK (status IN ('open','closed','reconciled')),
  opened_by      uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  opened_by_staff_id uuid REFERENCES public.crm_staff(id) ON DELETE SET NULL,
  opened_at      timestamptz NOT NULL DEFAULT now(),
  opening_float  numeric(12,2) NOT NULL DEFAULT 0,
  closed_by      uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  closed_at      timestamptz,
  expected_cash  numeric(12,2),
  counted_cash   numeric(12,2),
  cash_variance  numeric(12,2) GENERATED ALWAYS AS (counted_cash - expected_cash) STORED,
  notes          text,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS commerce_register_sessions_one_open
  ON public.commerce_register_sessions(tenant_id, location_id, register_code) NULLS NOT DISTINCT WHERE status = 'open';

CREATE TABLE IF NOT EXISTS public.platform_report_definitions (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  name          text NOT NULL,
  data_source   text NOT NULL,              -- table/view/RPC the report reads
  definition    jsonb NOT NULL DEFAULT '{}'::jsonb,
  columns       jsonb,
  filters       jsonb,
  schedule      text,                       -- cron text; NULL = on demand
  owner_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  is_shared     boolean NOT NULL DEFAULT true,
  is_active     boolean NOT NULL DEFAULT true,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, name)
);

-- ------------------------------------------------------------ triggers
CREATE OR REPLACE FUNCTION public.crm__appointment_before() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.appointment_number IS NULL OR NEW.appointment_number = '' THEN
    NEW.appointment_number := public.erp_next_document_number(NEW.tenant_id, 'appointment');
  END IF;
  NEW.block_starts_at := NEW.starts_at - make_interval(mins => NEW.buffer_before_minutes);
  NEW.block_ends_at   := NEW.ends_at   + make_interval(mins => NEW.buffer_after_minutes);
  NEW.updated_at := now();
  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    CASE NEW.status
      WHEN 'confirmed'   THEN NEW.confirmed_at  := coalesce(NEW.confirmed_at, now());
      WHEN 'checked_in'  THEN NEW.checked_in_at := coalesce(NEW.checked_in_at, now());
      WHEN 'in_progress' THEN NEW.started_at    := coalesce(NEW.started_at, now());
      WHEN 'completed'   THEN NEW.completed_at  := coalesce(NEW.completed_at, now());
      WHEN 'cancelled'   THEN NEW.cancelled_at  := coalesce(NEW.cancelled_at, now());
      WHEN 'no_show'     THEN NEW.no_show_at    := coalesce(NEW.no_show_at, now());
      ELSE NULL;
    END CASE;
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS crm_appointments_before ON public.crm_appointments;
CREATE TRIGGER crm_appointments_before BEFORE INSERT OR UPDATE ON public.crm_appointments
  FOR EACH ROW EXECUTE FUNCTION public.crm__appointment_before();

CREATE OR REPLACE FUNCTION public.crm__refresh_customer_visits(p_customer uuid) RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$
  UPDATE public.crm_customers c SET
    next_appointment_at = s.next_at, last_visit_at = coalesce(s.last_at, c.last_visit_at),
    total_visits = s.visits, no_show_rate = coalesce(s.no_show_rate, 0),
    cancellation_rate = coalesce(s.cancel_rate, 0), updated_at = now()
  FROM (SELECT min(starts_at) FILTER (WHERE status IN ('requested','scheduled','confirmed') AND starts_at > now()) AS next_at,
               max(coalesce(completed_at, starts_at)) FILTER (WHERE status = 'completed') AS last_at,
               count(*) FILTER (WHERE status = 'completed')::int AS visits,
               round(count(*) FILTER (WHERE status = 'no_show')::numeric
                     / nullif(count(*) FILTER (WHERE status IN ('completed','no_show')), 0), 4) AS no_show_rate,
               round(count(*) FILTER (WHERE status = 'cancelled')::numeric
                     / nullif(count(*) FILTER (WHERE status <> 'rescheduled'), 0), 4) AS cancel_rate
          FROM public.crm_appointments WHERE customer_id = p_customer) s
  WHERE c.id = p_customer $$;

CREATE OR REPLACE FUNCTION public.crm__appointment_after() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO public.crm_appointment_status_history(tenant_id, appointment_id, from_status, to_status, reason, changed_by)
    VALUES (NEW.tenant_id, NEW.id, CASE WHEN TG_OP = 'UPDATE' THEN OLD.status END, NEW.status,
            CASE WHEN NEW.status = 'cancelled' THEN NEW.cancellation_reason END, auth.uid());
  END IF;
  PERFORM public.crm__refresh_customer_visits(NEW.customer_id);
  IF TG_OP = 'UPDATE' AND OLD.customer_id IS DISTINCT FROM NEW.customer_id THEN
    PERFORM public.crm__refresh_customer_visits(OLD.customer_id);
  END IF;
  RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS crm_appointments_after ON public.crm_appointments;
CREATE TRIGGER crm_appointments_after AFTER INSERT OR UPDATE ON public.crm_appointments
  FOR EACH ROW EXECUTE FUNCTION public.crm__appointment_after();

-- event bus: outbox_emit / outbox_emit_lifecycle already contain crm_appointments branches
DROP TRIGGER IF EXISTS trg_outbox_appointment_created ON public.crm_appointments;
CREATE TRIGGER trg_outbox_appointment_created AFTER INSERT ON public.crm_appointments
  FOR EACH ROW EXECUTE FUNCTION public.outbox_emit();
DROP TRIGGER IF EXISTS trg_outbox_appointment_closed ON public.crm_appointments;
CREATE TRIGGER trg_outbox_appointment_closed AFTER UPDATE OF status ON public.crm_appointments
  FOR EACH ROW EXECUTE FUNCTION public.outbox_emit();
DROP TRIGGER IF EXISTS trg_outbox_appointment_lifecycle ON public.crm_appointments;
CREATE TRIGGER trg_outbox_appointment_lifecycle AFTER UPDATE OF status ON public.crm_appointments
  FOR EACH ROW EXECUTE FUNCTION public.outbox_emit_lifecycle();

-- ------------------------------------------------------------ RPCs
CREATE OR REPLACE FUNCTION public.crm__assert_member(p_tenant uuid) RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF current_user IN ('postgres','service_role','supabase_admin') OR auth.role() = 'service_role' THEN RETURN; END IF;
  IF NOT public.platform_is_tenant_member(p_tenant) THEN
    RAISE EXCEPTION 'not a member of tenant %', p_tenant USING ERRCODE = '42501';
  END IF;
END $$;

CREATE OR REPLACE FUNCTION public.crm__policy(p_tenant uuid, p_location uuid, p_service uuid)
RETURNS public.crm_booking_policies LANGUAGE sql STABLE AS $$
  SELECT p FROM (
    SELECT p, (p.location_id IS NOT NULL)::int + (p.service_id IS NOT NULL)::int * 2 AS score
      FROM public.crm_booking_policies p
     WHERE p.tenant_id = p_tenant
       AND (p.location_id IS NULL OR p.location_id = p_location)
       AND (p.service_id IS NULL OR p.service_id = p_service)
    UNION ALL
    SELECT ROW(NULL, p_tenant, NULL, NULL, 15, 60, 90, 0, 0, 24, 0, 0, false, NULL, true, true,
               'America/Chicago', now(), now())::public.crm_booking_policies, -1
  ) x ORDER BY score DESC LIMIT 1 $$;

CREATE OR REPLACE FUNCTION public.crm__service_minutes(p_service uuid, p_location uuid) RETURNS integer
LANGUAGE sql STABLE AS $$
  SELECT coalesce((SELECT a.duration_minutes FROM public.crm_service_location_availability a
                    WHERE a.service_id = p_service AND a.location_id = p_location AND a.is_active IS NOT FALSE LIMIT 1),
                  (SELECT s.default_duration_minutes FROM public.crm_services s WHERE s.id = p_service), 60) $$;

CREATE OR REPLACE FUNCTION public.crm_available_slots(p_tenant uuid, p_service uuid, p_date date,
                                                      p_location uuid DEFAULT NULL, p_staff uuid DEFAULT NULL)
RETURNS TABLE(staff_id uuid, staff_name text, starts_at timestamptz, ends_at timestamptz)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE pol public.crm_booking_policies; tz text; mins int;
BEGIN
  PERFORM public.crm__assert_member(p_tenant);
  pol  := public.crm__policy(p_tenant, p_location, p_service);
  tz   := coalesce((SELECT l.timezone FROM public.locations l WHERE l.id = p_location), pol.default_timezone);
  mins := public.crm__service_minutes(p_service, p_location);
  IF p_date > (now() AT TIME ZONE tz)::date + pol.max_advance_days THEN RETURN; END IF;
  RETURN QUERY
  WITH windows AS (
    SELECT st.id AS sid, st.display_name,
           (p_date + av.available_from) AT TIME ZONE tz AS w_from,
           (p_date + av.available_to)   AT TIME ZONE tz AS w_to
      FROM public.crm_staff st
      JOIN public.crm_staff_availability av ON av.staff_id = st.id
     WHERE st.tenant_id = p_tenant AND st.is_active IS NOT FALSE AND st.is_service_staff IS NOT FALSE
       AND (p_staff IS NULL OR st.id = p_staff)
       AND av.day_of_week = extract(dow FROM p_date)::int
       AND coalesce(av.availability_type, 'available') <> 'unavailable'
       AND (av.effective_from IS NULL OR av.effective_from <= p_date)
       AND (av.effective_to IS NULL OR av.effective_to >= p_date)
       AND (p_location IS NULL OR av.location_id IS NULL OR av.location_id = p_location)
    UNION ALL   -- one-off extra availability
    SELECT st.id, st.display_name, b.starts_at, b.ends_at
      FROM public.crm_staff_blocked_times b JOIN public.crm_staff st ON st.id = b.staff_id
     WHERE b.tenant_id = p_tenant AND b.block_type = 'extra_availability'
       AND (p_staff IS NULL OR st.id = p_staff)
       AND (b.starts_at AT TIME ZONE tz)::date = p_date
  ), cand AS (
    SELECT w.sid, w.display_name, g AS s, g + make_interval(mins => mins) AS e
      FROM windows w,
           generate_series(w.w_from, w.w_to - make_interval(mins => mins), make_interval(mins => pol.slot_interval_minutes)) g
  )
  SELECT DISTINCT c.sid, c.display_name, c.s, c.e
    FROM cand c
   WHERE c.s >= now() + make_interval(mins => pol.min_notice_minutes)
     AND NOT EXISTS (SELECT 1 FROM public.crm_appointments a
                      WHERE a.staff_id = c.sid
                        AND a.status IN ('requested','scheduled','confirmed','checked_in','in_progress')
                        AND tstzrange(a.block_starts_at, a.block_ends_at, '[)')
                            && tstzrange(c.s - make_interval(mins => pol.buffer_before_minutes),
                                         c.e + make_interval(mins => pol.buffer_after_minutes), '[)'))
     AND NOT EXISTS (SELECT 1 FROM public.crm_staff_blocked_times b
                      WHERE b.tenant_id = p_tenant AND b.block_type <> 'extra_availability'
                        AND (b.staff_id = c.sid OR (b.staff_id IS NULL AND (b.location_id IS NULL OR b.location_id = p_location)))
                        AND tstzrange(b.starts_at, b.ends_at, '[)') && tstzrange(c.s, c.e, '[)'))
   ORDER BY c.s, c.display_name;
END $$;

CREATE OR REPLACE FUNCTION public.crm_book_appointment(
  p_tenant uuid, p_customer uuid, p_service uuid, p_starts_at timestamptz,
  p_staff uuid DEFAULT NULL, p_location uuid DEFAULT NULL, p_dependent uuid DEFAULT NULL,
  p_resource uuid DEFAULT NULL, p_source_channel text DEFAULT 'staff', p_customer_notes text DEFAULT NULL,
  p_idempotency_key text DEFAULT NULL, p_duration_minutes integer DEFAULT NULL)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE pol public.crm_booking_policies; v uuid; mins int; v_staff uuid := p_staff; tz text; price numeric;
BEGIN
  PERFORM public.crm__assert_member(p_tenant);
  IF p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v FROM public.crm_appointments WHERE tenant_id = p_tenant AND idempotency_key = p_idempotency_key;
    IF v IS NOT NULL THEN RETURN v; END IF;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.crm_customers WHERE id = p_customer AND tenant_id = p_tenant) THEN
    RAISE EXCEPTION 'customer % not found in tenant', p_customer;
  END IF;
  pol  := public.crm__policy(p_tenant, p_location, p_service);
  IF p_source_channel IN ('online','portal') AND NOT pol.allow_online_booking THEN
    RAISE EXCEPTION 'online booking is disabled for this service/location';
  END IF;
  tz   := coalesce((SELECT timezone FROM public.locations WHERE id = p_location), pol.default_timezone);
  mins := coalesce(p_duration_minutes, public.crm__service_minutes(p_service, p_location));
  IF v_staff IS NULL THEN   -- first free qualified staff member for that exact start
    SELECT s.staff_id INTO v_staff FROM public.crm_available_slots(p_tenant, p_service, (p_starts_at AT TIME ZONE tz)::date, p_location) s
     WHERE s.starts_at = p_starts_at LIMIT 1;
  END IF;
  SELECT coalesce(a.price, s.default_price) INTO price FROM public.crm_services s
    LEFT JOIN public.crm_service_location_availability a ON a.service_id = s.id AND a.location_id = p_location
   WHERE s.id = p_service;
  BEGIN
    INSERT INTO public.crm_appointments(tenant_id, appointment_number, customer_id, dependent_id, location_id, staff_id, resource_id,
                                        service_id, status, starts_at, ends_at, buffer_before_minutes, buffer_after_minutes,
                                        timezone, source_channel, customer_notes, estimated_total, idempotency_key, created_by)
    VALUES (p_tenant, '', p_customer, p_dependent, p_location, v_staff, p_resource, p_service,
            CASE WHEN pol.auto_confirm THEN 'confirmed' ELSE 'requested' END,
            p_starts_at, p_starts_at + make_interval(mins => mins), pol.buffer_before_minutes, pol.buffer_after_minutes,
            tz, coalesce(p_source_channel, 'staff'), p_customer_notes, price, p_idempotency_key, auth.uid())
    RETURNING id INTO v;
  EXCEPTION WHEN exclusion_violation THEN
    RAISE EXCEPTION 'that time is no longer available for this staff member or resource' USING ERRCODE = 'P0001';
  END;
  IF p_service IS NOT NULL THEN
    INSERT INTO public.crm_appointment_services(tenant_id, appointment_id, dependent_id, service_id, staff_id, quantity,
                                                duration_minutes, unit_price, total, status)
    VALUES (p_tenant, v, p_dependent, p_service, v_staff, 1, mins, price, price, 'scheduled');
  END IF;
  RETURN v;
END $$;

CREATE OR REPLACE FUNCTION public.crm_reschedule_appointment(p_appointment uuid, p_new_starts_at timestamptz,
                                                             p_new_staff uuid DEFAULT NULL, p_reason text DEFAULT NULL)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE a public.crm_appointments; v uuid;
BEGIN
  SELECT * INTO a FROM public.crm_appointments WHERE id = p_appointment FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'appointment % not found', p_appointment; END IF;
  PERFORM public.crm__assert_member(a.tenant_id);
  IF a.status NOT IN ('requested','scheduled','confirmed') THEN
    RAISE EXCEPTION 'cannot reschedule an appointment that is %', a.status;
  END IF;
  UPDATE public.crm_appointments SET status = 'rescheduled', internal_notes = concat_ws(E'\n', internal_notes, p_reason)
   WHERE id = a.id;
  v := public.crm_book_appointment(a.tenant_id, a.customer_id, a.service_id, p_new_starts_at,
                                   coalesce(p_new_staff, a.staff_id), a.location_id, a.dependent_id, a.resource_id,
                                   a.source_channel, a.customer_notes, NULL,
                                   (extract(epoch FROM a.ends_at - a.starts_at) / 60)::int);
  UPDATE public.crm_appointments SET rescheduled_from_id = a.id, deposit_id = a.deposit_id, estimate_id = a.estimate_id
   WHERE id = v;
  RETURN v;
END $$;

CREATE OR REPLACE FUNCTION public.crm_cancel_appointment(p_appointment uuid, p_reason text DEFAULT NULL)
RETURNS public.crm_appointments LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE a public.crm_appointments; pol public.crm_booking_policies;
BEGIN
  SELECT * INTO a FROM public.crm_appointments WHERE id = p_appointment FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'appointment % not found', p_appointment; END IF;
  PERFORM public.crm__assert_member(a.tenant_id);
  IF a.status IN ('completed','cancelled','no_show','rescheduled') THEN
    RAISE EXCEPTION 'appointment is already %', a.status;
  END IF;
  pol := public.crm__policy(a.tenant_id, a.location_id, a.service_id);
  UPDATE public.crm_appointments
     SET status = 'cancelled', cancellation_reason = p_reason, cancelled_by = auth.uid(),
         late_cancel = (a.starts_at - now()) < make_interval(hours => pol.cancellation_window_hours)
   WHERE id = a.id RETURNING * INTO a;
  UPDATE public.crm_appointment_services SET status = 'cancelled' WHERE appointment_id = a.id AND status = 'scheduled';
  RETURN a;
END $$;

CREATE OR REPLACE FUNCTION public.crm_set_appointment_status(p_appointment uuid, p_status text, p_note text DEFAULT NULL)
RETURNS public.crm_appointments LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE a public.crm_appointments; ok boolean;
BEGIN
  SELECT * INTO a FROM public.crm_appointments WHERE id = p_appointment FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'appointment % not found', p_appointment; END IF;
  PERFORM public.crm__assert_member(a.tenant_id);
  ok := (a.status, p_status) IN (('requested','scheduled'), ('requested','confirmed'), ('scheduled','confirmed'),
                                 ('scheduled','checked_in'), ('confirmed','checked_in'), ('checked_in','in_progress'),
                                 ('scheduled','in_progress'), ('confirmed','in_progress'), ('in_progress','completed'),
                                 ('checked_in','completed'), ('scheduled','no_show'), ('confirmed','no_show'),
                                 ('requested','no_show'));
  IF NOT ok THEN RAISE EXCEPTION 'invalid appointment transition % -> %', a.status, p_status; END IF;
  UPDATE public.crm_appointments SET status = p_status,
         internal_notes = CASE WHEN p_note IS NULL THEN internal_notes ELSE concat_ws(E'\n', internal_notes, p_note) END
   WHERE id = a.id RETURNING * INTO a;
  UPDATE public.crm_appointment_services SET status = CASE p_status WHEN 'in_progress' THEN 'in_progress'
                                                                     WHEN 'completed' THEN 'completed'
                                                                     WHEN 'no_show' THEN 'skipped' ELSE status END
   WHERE appointment_id = a.id AND status NOT IN ('completed','cancelled');
  RETURN a;
END $$;

REVOKE ALL ON FUNCTION public.crm_available_slots(uuid,uuid,date,uuid,uuid), public.crm_book_appointment(uuid,uuid,uuid,timestamptz,uuid,uuid,uuid,uuid,text,text,text,integer),
  public.crm_reschedule_appointment(uuid,timestamptz,uuid,text), public.crm_cancel_appointment(uuid,text),
  public.crm_set_appointment_status(uuid,text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.crm_available_slots(uuid,uuid,date,uuid,uuid), public.crm_book_appointment(uuid,uuid,uuid,timestamptz,uuid,uuid,uuid,uuid,text,text,text,integer),
  public.crm_reschedule_appointment(uuid,timestamptz,uuid,text), public.crm_cancel_appointment(uuid,text),
  public.crm_set_appointment_status(uuid,text,text) TO authenticated, service_role;

-- crm_appointment_services has no primary key, so crm_notes.service_record_id cannot reference it
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.crm_appointment_services'::regclass AND contype = 'p') THEN
    UPDATE public.crm_appointment_services SET id = gen_random_uuid() WHERE id IS NULL;
    ALTER TABLE public.crm_appointment_services ADD CONSTRAINT crm_appointment_services_pkey PRIMARY KEY (id);
  END IF;
END $$;

-- ------------------------------------------------------------ dependents link table
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.crm_party_dependents'::regclass
                  AND contype = 'f' AND conkey = ARRAY[(SELECT attnum FROM pg_attribute WHERE attrelid = 'public.crm_party_dependents'::regclass AND attname = 'dependent_id')]::int2[]) THEN
    ALTER TABLE public.crm_party_dependents ADD CONSTRAINT crm_party_dependents_dependent_id_fk
      FOREIGN KEY (dependent_id) REFERENCES public.crm_dependents(id) ON DELETE CASCADE NOT VALID;
  END IF;
END $$;

-- ------------------------------------------------------------ legacy calendar data
-- blocked_times / availability use text staffId and text date/time. Resolve
-- staff by crm_staff id, legacy staff email, or legacy staff name.
CREATE OR REPLACE FUNCTION unify.resolve_staff(p_tenant uuid, p_legacy text) RETURNS uuid LANGUAGE sql STABLE AS $$
  SELECT coalesce(
    (SELECT id FROM public.crm_staff WHERE tenant_id = p_tenant AND id::text = p_legacy),
    (SELECT c.id FROM public.staff s JOIN public.crm_staff c ON c.tenant_id = p_tenant
            AND lower(c.email) = lower(s.email) WHERE s.id = p_legacy LIMIT 1),
    (SELECT c.id FROM public.staff s JOIN public.crm_staff c ON c.tenant_id = p_tenant
            AND lower(c.display_name) = lower(s.name) WHERE s.id = p_legacy LIMIT 1)) $$;

DO $$
DECLARE tz text := 'America/Chicago'; n int := 0; r record;
BEGIN
  IF to_regclass('public.blocked_times') IS NOT NULL THEN
    FOR r IN SELECT b.*, unify.resolve_staff(b.tenant_id, b."staffId") AS sid FROM public.blocked_times b LOOP
      BEGIN
        INSERT INTO public.crm_staff_blocked_times(tenant_id, staff_id, starts_at, ends_at, block_type, reason, legacy_source, legacy_id)
        VALUES (r.tenant_id, r.sid,
                (r.date::date + coalesce(nullif(r."startTime", ''), '00:00')::time) AT TIME ZONE tz,
                (r.date::date + coalesce(nullif(r."endTime", ''), '23:59')::time) AT TIME ZONE tz,
                'blocked', r.reason, 'blocked_times', r.id)
        ON CONFLICT (legacy_source, legacy_id) DO NOTHING;
        IF r."staffId" IS NOT NULL AND r.sid IS NULL THEN
          PERFORM unify.log('blocked_times', r.id, 'staff_unresolved', r."staffId" || ' -> saved as business-wide block');
        END IF;
        n := n + 1;
      EXCEPTION WHEN others THEN PERFORM unify.log('blocked_times', r.id, 'migrate_failed', SQLERRM);
      END;
    END LOOP;
  END IF;
  IF to_regclass('public.availability') IS NOT NULL THEN
    FOR r IN SELECT a.*, unify.resolve_staff(a.tenant_id, a."staffId") AS sid FROM public.availability a LOOP
      BEGIN
        IF r.sid IS NULL THEN
          PERFORM unify.log('availability', r.id, 'staff_unresolved', coalesce(r."staffId", '(null)')); CONTINUE;
        END IF;
        INSERT INTO public.crm_staff_blocked_times(tenant_id, staff_id, starts_at, ends_at, block_type, reason, legacy_source, legacy_id)
        VALUES (r.tenant_id, r.sid,
                (r.date::date + r."startTime"::time) AT TIME ZONE tz, (r.date::date + r."endTime"::time) AT TIME ZONE tz,
                CASE WHEN lower(coalesce(r.status, 'available')) IN ('available','open') THEN 'extra_availability' ELSE 'blocked' END,
                'legacy availability: ' || coalesce(r.status, ''), 'availability', r.id)
        ON CONFLICT (legacy_source, legacy_id) DO NOTHING;
        n := n + 1;
      EXCEPTION WHEN others THEN PERFORM unify.log('availability', r.id, 'migrate_failed', SQLERRM);
      END;
    END LOOP;
  END IF;
  PERFORM unify.log('calendar', NULL, 'legacy_calendar_migrated', n::text);
END $$;

-- ------------------------------------------------------------ RLS
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['crm_dependents','crm_appointment_resources','crm_booking_policies','crm_appointments',
                           'crm_appointment_status_history','crm_staff_blocked_times','commerce_register_sessions',
                           'platform_report_definitions'] LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('DROP POLICY IF EXISTS unify_tenant_rw ON public.%I', t);
    EXECUTE format('CREATE POLICY unify_tenant_rw ON public.%I FOR ALL TO authenticated
                      USING (public.platform_is_tenant_member(tenant_id)) WITH CHECK (public.platform_is_tenant_member(tenant_id))', t);
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
  END LOOP;
END $$;
-- history is append-only from the app's point of view
REVOKE INSERT, UPDATE, DELETE ON public.crm_appointment_status_history FROM authenticated;

COMMIT;

SELECT 'appointments domain ready' AS status,
       (SELECT count(*) FROM public.crm_staff_blocked_times) AS calendar_blocks_migrated,
       (SELECT count(*) FROM unify.run_log WHERE action = 'staff_unresolved') AS legacy_calendar_rows_unresolved;

-- ---------------------------------------------------------------------
-- 05_catalog_products/06f_catalog_listing_map.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- 06f  Catalog -> Listing taxonomy map (inventory stays its own layer)
--
--   Product Catalog  global, no tenant. Every source lands here with its own names intact:
--                    POD catalogs, direct supplier APIs, feeds, marketplace sellers.
--                      suppliers                    the source
--                      catalog_source_categories    NEW: the source's own category tree, verbatim
--                      supplier_catalog_products    products (+ source_category_id / source_category_path)
--                      supplier_catalog_variants    variants
--   Listing          per tenant. The categories a business names and publishes on its site.
--                      taxonomy_nodes               the tenant's published tree (Unsaid's folder tree is one tenant's listing)
--                      product_taxonomy_links       the publish result: catalog product shown under a listing node
--   Map              per tenant. Connects the two; nobody's site has to use a supplier's names.
--                      listing_category_map         NEW: source category / source path / product pin / rule -> listing node
--                      listing_publish()            NEW: applies the map, writes links, leaves manual links alone
--   Inventory        stock + availability only, keyed by SKU. Defines no categories.
--                      listing_v_availability       NEW: what a listing can actually sell right now
--
-- Idempotent. Safe to re-run. Run after 06e.
-- =====================================================================
SET search_path = public, pg_catalog;

-- =====================================================================
-- A. Catalog layer: keep every source's category names intact
-- =====================================================================
CREATE TABLE IF NOT EXISTS public.catalog_source_categories (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  supplier_id    uuid NOT NULL REFERENCES public.suppliers(id) ON DELETE CASCADE,
  external_id    text,                          -- the source's own id, when it has one
  name           text NOT NULL,                 -- verbatim, e.g. "Men's Clothing" or "T-Shirts"
  parent_id      uuid REFERENCES public.catalog_source_categories(id) ON DELETE CASCADE,
  path           text NOT NULL,                 -- verbatim names joined by " / ", e.g. "Men's Clothing / T-Shirts"
  depth          smallint NOT NULL DEFAULT 1 CHECK (depth BETWEEN 1 AND 12),
  product_count  integer NOT NULL DEFAULT 0,
  status         text NOT NULL DEFAULT 'active' CHECK (status IN ('active','retired')),
  raw            jsonb NOT NULL DEFAULT '{}'::jsonb,
  first_seen_at  timestamptz NOT NULL DEFAULT now(),
  last_seen_at   timestamptz NOT NULL DEFAULT now(),
  UNIQUE (supplier_id, path)
);
CREATE UNIQUE INDEX IF NOT EXISTS catalog_source_categories_ext_uq
  ON public.catalog_source_categories(supplier_id, external_id) WHERE external_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS catalog_source_categories_parent_idx ON public.catalog_source_categories(parent_id);
COMMENT ON TABLE public.catalog_source_categories IS
  'Global product catalog: each source''s own category tree, names intact. Listing categories never live here; listing_category_map connects them.';

ALTER TABLE public.supplier_catalog_products
  ADD COLUMN IF NOT EXISTS source_category_id   uuid REFERENCES public.catalog_source_categories(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS source_category_path text,     -- what the source called it; the ingest only has to set this
  ADD COLUMN IF NOT EXISTS source_product_type  text;     -- e.g. Printful "T-SHIRT", Shopify product_type
CREATE INDEX IF NOT EXISTS supplier_catalog_products_source_cat_idx ON public.supplier_catalog_products(source_category_id);
COMMENT ON COLUMN public.supplier_catalog_products.category_id IS
  'LEGACY: points at a tenant categories row from a global table (layer leak). 06f turned these into listing_category_map product pins. New code: source_category_id + listing_category_map.';

-- normalise a source path: trim each segment, keep the source's spelling and case
CREATE OR REPLACE FUNCTION public.catalog__norm_path(p text) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = public, pg_catalog AS $$
  SELECT nullif(array_to_string(array(SELECT btrim(s) FROM unnest(regexp_split_to_array(coalesce(p, ''), '\s*(/|>|\|)\s*')) s
                                       WHERE btrim(s) <> ''), ' / '), '') $$;

-- find or create a source category (and its parents) from a verbatim path. APIs / feeds call this.
CREATE OR REPLACE FUNCTION public.catalog_upsert_source_category(p_supplier uuid, p_path text, p_external_id text DEFAULT NULL,
  p_raw jsonb DEFAULT NULL)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog AS $$
DECLARE segs text[]; cur text; parent uuid; node uuid;
BEGIN
  segs := regexp_split_to_array(public.catalog__norm_path(p_path), ' / ');
  IF segs IS NULL OR array_length(segs, 1) IS NULL THEN RETURN NULL; END IF;
  FOR i IN 1 .. array_length(segs, 1) LOOP
    cur := array_to_string(segs[1:i], ' / ');
    INSERT INTO public.catalog_source_categories(supplier_id, name, parent_id, path, depth, external_id, raw)
    VALUES (p_supplier, segs[i], parent, cur, i,
            CASE WHEN i = array_length(segs, 1) THEN p_external_id END,
            CASE WHEN i = array_length(segs, 1) THEN coalesce(p_raw, '{}'::jsonb) ELSE '{}'::jsonb END)
    ON CONFLICT (supplier_id, path) DO UPDATE
      SET last_seen_at = now(), status = 'active',
          external_id = coalesce(EXCLUDED.external_id, catalog_source_categories.external_id),
          raw = CASE WHEN EXCLUDED.raw = '{}'::jsonb THEN catalog_source_categories.raw ELSE EXCLUDED.raw END
    RETURNING id INTO node;
    parent := node;
  END LOOP;
  RETURN node;
END $$;

-- any ingest path (API sync, feed import, browser catalog, manual) only has to set source_category_path
CREATE OR REPLACE FUNCTION public.catalog__product_source_category() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog AS $$
BEGIN
  IF NEW.source_category_path IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW.source_category_path IS DISTINCT FROM OLD.source_category_path OR NEW.source_category_id IS NULL) THEN
    NEW.source_category_path := public.catalog__norm_path(NEW.source_category_path);
    NEW.source_category_id := public.catalog_upsert_source_category(NEW.supplier_id, NEW.source_category_path);
  ELSIF NEW.source_category_id IS NOT NULL AND NEW.source_category_path IS NULL THEN
    SELECT c.path INTO NEW.source_category_path FROM public.catalog_source_categories c WHERE c.id = NEW.source_category_id;
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS trg_source_category ON public.supplier_catalog_products;
CREATE TRIGGER trg_source_category BEFORE INSERT OR UPDATE OF source_category_path, source_category_id ON public.supplier_catalog_products
  FOR EACH ROW EXECUTE FUNCTION public.catalog__product_source_category();

-- =====================================================================
-- B. Listing layer: tenant-named, published categories
-- =====================================================================
-- node_type was a pet-store CHECK ('animal','department','subcategory','category'); now a picklist
INSERT INTO public.platform_picklist_values(tenant_id, list_code, value, label, sort_order, pack_code)
SELECT NULL, l, v, lb, o, p FROM (VALUES
  ('listing_node_type','department','Department',10,NULL),('listing_node_type','category','Category',20,NULL),
  ('listing_node_type','subcategory','Subcategory',30,NULL),('listing_node_type','collection','Collection',40,NULL),
  ('listing_node_type','audience','Audience (who it is for)',50,NULL),('listing_node_type','brand','Brand',60,NULL),
  ('listing_node_type','landing','Landing page',70,NULL),
  ('listing_node_type','animal','Animal',200,'pet_grooming')
) s(l, v, lb, o, p)
ON CONFLICT DO NOTHING;
DO $$
DECLARE n int;
BEGIN
  IF EXISTS (SELECT 1 FROM unify.settings WHERE key = '06f.listing_picklists_scoped') THEN RETURN; END IF;
  UPDATE public.platform_picklist_values SET is_active = false
   WHERE tenant_id IS NULL AND list_code = 'listing_node_type' AND pack_code IS NOT NULL;
  -- tenants already using 'animal' (Unsaid) keep it as their own value
  INSERT INTO public.platform_picklist_values(tenant_id, list_code, value, label, sort_order, pack_code)
  SELECT DISTINCT tn.tenant_id, 'listing_node_type', tn.node_type, initcap(tn.node_type), 200, NULL
    FROM public.taxonomy_nodes tn
   WHERE NOT EXISTS (SELECT 1 FROM public.platform_picklist_values v
                      WHERE v.list_code = 'listing_node_type' AND v.value = tn.node_type AND v.tenant_id IS NULL AND v.is_active)
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN PERFORM unify.log('06f', 'taxonomy_nodes.node_type', 'tenant_values_kept', n || ' tenant/value pairs'); END IF;
  INSERT INTO unify.settings(key, value, note) VALUES ('06f.listing_picklists_scoped', now()::text, 'listing node types scoped');
END $$;
INSERT INTO public.platform_pack_items(pack_code, item_type, item_key, payload, sort_order)
VALUES ('pet_grooming', 'picklist', 'listing_node_type', '{"values":["animal"]}', 15)
ON CONFLICT (pack_code, item_type, item_key) DO NOTHING;

ALTER TABLE public.taxonomy_nodes DROP CONSTRAINT IF EXISTS taxonomy_nodes_node_type_check;
DROP TRIGGER IF EXISTS trg_picklist_node_type ON public.taxonomy_nodes;
CREATE TRIGGER trg_picklist_node_type BEFORE INSERT OR UPDATE OF node_type ON public.taxonomy_nodes
  FOR EACH ROW EXECUTE FUNCTION public.platform__picklist_guard('node_type', 'listing_node_type');
ALTER TABLE public.taxonomy_nodes
  ADD COLUMN IF NOT EXISTS published_at timestamptz,
  ADD COLUMN IF NOT EXISTS seo_title    text,
  ADD COLUMN IF NOT EXISTS seo_description text;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'taxonomy_nodes_tenant_id_id_key') THEN
    ALTER TABLE public.taxonomy_nodes ADD CONSTRAINT taxonomy_nodes_tenant_id_id_key UNIQUE (tenant_id, id);
  END IF;
END $$;
COMMENT ON TABLE public.taxonomy_nodes IS
  'Listing layer: the categories a tenant names and publishes on its own site. Never a supplier''s structure.';

-- the second tree: categories (used by products.category_id, overrides, supplier memory). Bridge each row to a listing node.
ALTER TABLE public.categories ADD COLUMN IF NOT EXISTS listing_node_id uuid REFERENCES public.taxonomy_nodes(id) ON DELETE SET NULL;
DO $$
DECLARE r record; p text; nid uuid; n int := 0;
BEGIN
  FOR r IN
    WITH RECURSIVE t AS (
      SELECT c.id, c.tenant_id, c.parent_id, c.name, c.slug, c.sort_order, c.is_active, c.slug::text AS path, 1 AS d, NULL::uuid AS parent_node
        FROM public.categories c WHERE c.parent_id IS NULL
      UNION ALL
      SELECT c.id, c.tenant_id, c.parent_id, c.name, c.slug, c.sort_order, c.is_active, t.path || '/' || c.slug, t.d + 1, NULL
        FROM public.categories c JOIN t ON t.id = c.parent_id)
    SELECT * FROM t WHERE NOT EXISTS (SELECT 1 FROM public.categories x WHERE x.id = t.id AND x.listing_node_id IS NOT NULL)
    ORDER BY d
  LOOP
    INSERT INTO public.taxonomy_nodes(tenant_id, parent_id, node_type, name, slug, path, depth, sort_order, is_associated, is_featured, is_gated, status, source_text)
    VALUES (r.tenant_id, (SELECT listing_node_id FROM public.categories WHERE id = r.parent_id),
            CASE WHEN r.d = 1 THEN 'department' WHEN r.d = 2 THEN 'category' ELSE 'subcategory' END,
            r.name, r.slug, r.path, r.d, coalesce(r.sort_order, 0), false, false, false,
            CASE WHEN r.is_active THEN 'published' ELSE 'draft' END, 'categories:' || r.id)
    ON CONFLICT (tenant_id, path) DO UPDATE SET updated_at = now()
    RETURNING id INTO nid;
    UPDATE public.categories SET listing_node_id = nid WHERE id = r.id;
    n := n + 1;
  END LOOP;
  IF n > 0 THEN PERFORM unify.log('06f', 'categories', 'bridged_to_listing', n || ' rows'); END IF;
END $$;

-- =====================================================================
-- C. Publish result: product_taxonomy_links becomes tenant-safe and knows where it came from
-- =====================================================================
ALTER TABLE public.product_taxonomy_links
  ADD COLUMN IF NOT EXISTS node_id    uuid,
  ADD COLUMN IF NOT EXISTS source     text NOT NULL DEFAULT 'manual',
  ADD COLUMN IF NOT EXISTS map_id     uuid,
  ADD COLUMN IF NOT EXISTS sort_order integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'product_taxonomy_links_source_check') THEN
    ALTER TABLE public.product_taxonomy_links ADD CONSTRAINT product_taxonomy_links_source_check CHECK (source IN ('manual','map','import'));
  END IF;
END $$;
-- links that name a path the tenant has no node for: create the node chain (they were live, so published) and log it
DO $$
DECLARE r record; segs text[]; i int; cur text; parent uuid; nid uuid; n int := 0;
BEGIN
  FOR r IN SELECT DISTINCT l.tenant_id, l.path FROM public.product_taxonomy_links l
            WHERE l.node_id IS NULL AND btrim(coalesce(l.path, '')) <> ''
              AND NOT EXISTS (SELECT 1 FROM public.taxonomy_nodes t WHERE t.tenant_id = l.tenant_id AND t.path = l.path) LOOP
    segs := array(SELECT s FROM unnest(string_to_array(btrim(r.path, '/'), '/')) s WHERE s <> '');
    parent := NULL;
    FOR i IN 1 .. coalesce(array_length(segs, 1), 0) LOOP
      cur := array_to_string(segs[1:i], '/');
      SELECT id INTO nid FROM public.taxonomy_nodes WHERE tenant_id = r.tenant_id AND path = cur;
      IF nid IS NULL THEN
        INSERT INTO public.taxonomy_nodes(tenant_id, parent_id, node_type, name, slug, path, depth, sort_order, is_associated, is_featured, is_gated, status, source_text)
        VALUES (r.tenant_id, parent, CASE i WHEN 1 THEN 'department' WHEN 2 THEN 'category' ELSE 'subcategory' END,
                initcap(replace(segs[i], '-', ' ')), segs[i], cur, i, 0, false, false, false, 'published', 'auto: product_taxonomy_links')
        RETURNING id INTO nid;
        n := n + 1;
      END IF;
      parent := nid;
    END LOOP;
  END LOOP;
  IF n > 0 THEN PERFORM unify.log('06f', 'taxonomy_nodes', 'created_for_orphan_links', n || ' listing nodes created from link paths; rename them in Catalog > Listing'); END IF;
END $$;
UPDATE public.product_taxonomy_links l SET node_id = n.id
  FROM public.taxonomy_nodes n WHERE l.node_id IS NULL AND n.tenant_id = l.tenant_id AND n.path = l.path;
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.product_taxonomy_links WHERE node_id IS NULL;
  IF n > 0 THEN PERFORM unify.log('06f', 'product_taxonomy_links', 'path_without_listing_node', n || ' links point at a path the tenant has no node for'); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'product_taxonomy_links_node_fk') THEN
    ALTER TABLE public.product_taxonomy_links ADD CONSTRAINT product_taxonomy_links_node_fk
      FOREIGN KEY (tenant_id, node_id) REFERENCES public.taxonomy_nodes(tenant_id, id) ON DELETE CASCADE;
  END IF;
  -- UNIQUE (path, product_id) had no tenant: two shops could not list the same catalog product under the same path
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'product_taxonomy_links_tenant_path_product_key') THEN
    ALTER TABLE public.product_taxonomy_links ADD CONSTRAINT product_taxonomy_links_tenant_path_product_key UNIQUE (tenant_id, path, product_id);
  END IF;
  IF EXISTS (SELECT 1 FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace
              AND p.prosrc ~* 'product_taxonomy_links' AND p.prosrc ~* 'on\s+conflict\s*\(\s*path\s*,\s*product_id\s*\)') THEN
    PERFORM unify.log('06f', 'product_taxonomy_links_path_product_id_key', 'kept', 'a function still uses ON CONFLICT (path, product_id); switch it to (tenant_id, path, product_id) then drop');
  ELSE
    ALTER TABLE public.product_taxonomy_links DROP CONSTRAINT IF EXISTS product_taxonomy_links_path_product_id_key;
  END IF;
END $$;
CREATE INDEX IF NOT EXISTS product_taxonomy_links_node_idx ON public.product_taxonomy_links(node_id, sort_order);
CREATE INDEX IF NOT EXISTS product_taxonomy_links_tenant_product_idx ON public.product_taxonomy_links(tenant_id, product_id);

-- a link can be written with either path or node; the other is filled in, and both must belong to the tenant
CREATE OR REPLACE FUNCTION public.listing__link_guard() RETURNS trigger
LANGUAGE plpgsql SET search_path = public, pg_catalog AS $$
DECLARE n public.taxonomy_nodes;
BEGIN
  IF NEW.node_id IS NOT NULL THEN
    SELECT * INTO n FROM public.taxonomy_nodes WHERE id = NEW.node_id;
  ELSE
    SELECT * INTO n FROM public.taxonomy_nodes WHERE tenant_id = NEW.tenant_id AND path = NEW.path;
  END IF;
  IF n.id IS NULL THEN
    RAISE EXCEPTION 'listing category % does not exist for this tenant', coalesce(NEW.path, NEW.node_id::text) USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF n.tenant_id <> NEW.tenant_id THEN RAISE EXCEPTION 'listing category belongs to another tenant' USING ERRCODE = 'check_violation'; END IF;
  NEW.node_id := n.id; NEW.path := n.path; NEW.updated_at := now();
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS trg_listing_link_guard ON public.product_taxonomy_links;
CREATE TRIGGER trg_listing_link_guard BEFORE INSERT OR UPDATE OF node_id, path, tenant_id ON public.product_taxonomy_links
  FOR EACH ROW EXECUTE FUNCTION public.listing__link_guard();

-- renaming / moving a listing node keeps its links (and children's links) in step
CREATE OR REPLACE FUNCTION public.listing__node_path_moved() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog AS $$
BEGIN
  IF NEW.path IS DISTINCT FROM OLD.path THEN
    UPDATE public.product_taxonomy_links SET path = NEW.path, updated_at = now() WHERE node_id = NEW.id;
  END IF;
  IF NEW.status = 'published' AND OLD.status IS DISTINCT FROM 'published' AND NEW.published_at IS NULL THEN
    UPDATE public.taxonomy_nodes SET published_at = now() WHERE id = NEW.id;
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS trg_listing_node_moved ON public.taxonomy_nodes;
CREATE TRIGGER trg_listing_node_moved AFTER UPDATE OF path, status ON public.taxonomy_nodes
  FOR EACH ROW EXECUTE FUNCTION public.listing__node_path_moved();

-- =====================================================================
-- D. The map: catalog -> listing, per tenant
-- =====================================================================
CREATE TABLE IF NOT EXISTS public.listing_category_map (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id           uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  node_id             uuid NOT NULL,                               -- the tenant's listing category
  match_kind          text NOT NULL CHECK (match_kind IN ('source_category','source_path','product','rule')),
  source_category_id  uuid REFERENCES public.catalog_source_categories(id) ON DELETE CASCADE,
  supplier_id         uuid REFERENCES public.suppliers(id) ON DELETE CASCADE,  -- narrows source_path / rule to one source
  source_path_prefix  text,                                        -- verbatim prefix, e.g. "Men's Clothing / T-Shirts"
  catalog_product_id  uuid REFERENCES public.supplier_catalog_products(id) ON DELETE CASCADE,
  rule                jsonb NOT NULL DEFAULT '{}'::jsonb,           -- {"brand_in":[..],"name_ilike":"%hoodie%","product_type_in":[..],"supplier_kind_in":["pod"]}
  include_descendants boolean NOT NULL DEFAULT true,
  effect              text NOT NULL DEFAULT 'include' CHECK (effect IN ('include','exclude')),
  priority            integer NOT NULL DEFAULT 100,                 -- lower wins when choosing a product's primary category
  is_primary          boolean NOT NULL DEFAULT false,
  status              text NOT NULL DEFAULT 'active' CHECK (status IN ('active','paused')),
  notes               text,
  created_by          uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (tenant_id, node_id) REFERENCES public.taxonomy_nodes(tenant_id, id) ON DELETE CASCADE,
  CHECK (match_kind <> 'source_category' OR source_category_id IS NOT NULL),
  CHECK (match_kind <> 'source_path' OR source_path_prefix IS NOT NULL),
  CHECK (match_kind <> 'product' OR catalog_product_id IS NOT NULL),
  CHECK (match_kind <> 'rule' OR rule <> '{}'::jsonb)
);
CREATE UNIQUE INDEX IF NOT EXISTS listing_category_map_uq ON public.listing_category_map
  (tenant_id, node_id, match_kind, effect,
   coalesce(source_category_id, '00000000-0000-0000-0000-000000000000'::uuid),
   coalesce(supplier_id, '00000000-0000-0000-0000-000000000000'::uuid),
   coalesce(source_path_prefix, ''), coalesce(catalog_product_id, '00000000-0000-0000-0000-000000000000'::uuid), rule);
CREATE INDEX IF NOT EXISTS listing_category_map_source_idx ON public.listing_category_map(source_category_id) WHERE source_category_id IS NOT NULL;
COMMENT ON TABLE public.listing_category_map IS
  'The taxonomy map. Connects global catalog products / source categories to a tenant''s own listing categories. listing_publish() applies it.';
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'product_taxonomy_links_map_fk') THEN
    ALTER TABLE public.product_taxonomy_links ADD CONSTRAINT product_taxonomy_links_map_fk
      FOREIGN KEY (map_id) REFERENCES public.listing_category_map(id) ON DELETE SET NULL;
  END IF;
END $$;

-- which catalog products does one map row match?
CREATE OR REPLACE FUNCTION public.listing__map_matches(m public.listing_category_map)
RETURNS SETOF uuid LANGUAGE sql STABLE SET search_path = public, pg_catalog AS $$
  SELECT p.id
    FROM public.supplier_catalog_products p
    JOIN public.suppliers s ON s.id = p.supplier_id
    LEFT JOIN public.catalog_source_categories c ON c.id = p.source_category_id
   WHERE NOT p.is_hidden
     AND (m.supplier_id IS NULL OR p.supplier_id = m.supplier_id)
     AND CASE m.match_kind
       WHEN 'product' THEN p.id = m.catalog_product_id
       WHEN 'source_category' THEN p.source_category_id = m.source_category_id
            OR (m.include_descendants AND c.id IS NOT NULL AND EXISTS (
                  SELECT 1 FROM public.catalog_source_categories root
                   WHERE root.id = m.source_category_id AND root.supplier_id = c.supplier_id
                     AND c.path LIKE replace(replace(root.path, '%', '\%'), '_', '\_') || ' / %'))
       WHEN 'source_path' THEN lower(p.source_category_path) = lower(public.catalog__norm_path(m.source_path_prefix))
            OR (m.include_descendants AND lower(p.source_category_path) LIKE
                  lower(replace(replace(public.catalog__norm_path(m.source_path_prefix), '%', '\%'), '_', '\_')) || ' / %')
       WHEN 'rule' THEN
            (NOT (m.rule ? 'brand_in') OR p.brand_name = ANY (ARRAY(SELECT jsonb_array_elements_text(m.rule -> 'brand_in'))))
        AND (NOT (m.rule ? 'name_ilike') OR p.name ILIKE (m.rule ->> 'name_ilike'))
        AND (NOT (m.rule ? 'product_type_in') OR p.source_product_type = ANY (ARRAY(SELECT jsonb_array_elements_text(m.rule -> 'product_type_in'))))
        AND (NOT (m.rule ? 'supplier_kind_in') OR s.kind = ANY (ARRAY(SELECT jsonb_array_elements_text(m.rule -> 'supplier_kind_in'))))
        AND (NOT (m.rule ? 'source_path_like') OR p.source_category_path ILIKE (m.rule ->> 'source_path_like'))
       ELSE false END $$;

-- the publish step: apply the map for one listing node (or all of a tenant's nodes)
CREATE OR REPLACE FUNCTION public.listing_publish(p_tenant uuid, p_node uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog AS $$
DECLARE nd record; added int := 0; removed int := 0; kept int := 0; nodes int := 0; x int;
BEGIN
  IF NOT (public.platform__is_service() OR public.platform_has_role(p_tenant, 'manager')
          OR public.platform_has_permission(p_tenant, 'catalog.publish')) THEN
    RAISE EXCEPTION 'not allowed to publish listings for this tenant' USING ERRCODE = 'insufficient_privilege';
  END IF;
  FOR nd IN SELECT n.* FROM public.taxonomy_nodes n
             WHERE n.tenant_id = p_tenant AND (p_node IS NULL OR n.id = p_node) AND n.status <> 'archived' LOOP
    nodes := nodes + 1;
    CREATE TEMP TABLE IF NOT EXISTS _listing_want(product_id uuid PRIMARY KEY, map_id uuid, priority int, is_primary boolean) ON COMMIT DROP;
    TRUNCATE _listing_want;
    INSERT INTO _listing_want
    SELECT DISTINCT ON (x.pid) x.pid, m.id, m.priority, m.is_primary
      FROM public.listing_category_map m, LATERAL public.listing__map_matches(m) AS x(pid)
     WHERE m.tenant_id = p_tenant AND m.node_id = nd.id AND m.status = 'active' AND m.effect = 'include'
     ORDER BY x.pid, m.is_primary DESC, m.priority, m.created_at;
    DELETE FROM _listing_want w
     WHERE EXISTS (SELECT 1 FROM public.listing_category_map m, LATERAL public.listing__map_matches(m) AS x(pid)
                    WHERE m.tenant_id = p_tenant AND m.node_id = nd.id AND m.status = 'active' AND m.effect = 'exclude' AND x.pid = w.product_id);
    -- stale map links go; manual links are never touched
    DELETE FROM public.product_taxonomy_links l
     WHERE l.tenant_id = p_tenant AND l.node_id = nd.id AND l.source = 'map'
       AND NOT EXISTS (SELECT 1 FROM _listing_want w WHERE w.product_id = l.product_id);
    GET DIAGNOSTICS x = ROW_COUNT; removed := removed + x;
    SELECT count(*) INTO x FROM _listing_want w JOIN public.product_taxonomy_links l
      ON l.tenant_id = p_tenant AND l.path = nd.path AND l.product_id = w.product_id;
    kept := kept + x;
    INSERT INTO public.product_taxonomy_links(tenant_id, path, node_id, product_id, is_primary, rule, source, map_id)
    SELECT p_tenant, nd.path, nd.id, w.product_id, false, 'map:' || w.map_id, 'map', w.map_id FROM _listing_want w
    ON CONFLICT (tenant_id, path, product_id) DO UPDATE
      SET map_id = CASE WHEN product_taxonomy_links.source = 'map' THEN EXCLUDED.map_id ELSE product_taxonomy_links.map_id END,
          updated_at = now();
    GET DIAGNOSTICS x = ROW_COUNT; added := added + x;
  END LOOP;
  added := greatest(added - kept, 0);
  -- one primary listing category per product: a manual primary wins, else the is_primary / lowest-priority map, else the deepest node
  WITH ranked AS (
    SELECT l.id, row_number() OVER (PARTITION BY l.product_id
             ORDER BY (l.source = 'manual' AND l.is_primary) DESC, coalesce(m.is_primary, false) DESC,
                      coalesce(m.priority, 1000), n.depth DESC, l.created_at) AS rn
      FROM public.product_taxonomy_links l
      JOIN public.taxonomy_nodes n ON n.id = l.node_id
      LEFT JOIN public.listing_category_map m ON m.id = l.map_id
     WHERE l.tenant_id = p_tenant)
  UPDATE public.product_taxonomy_links l SET is_primary = (r.rn = 1)
    FROM ranked r WHERE r.id = l.id AND l.is_primary IS DISTINCT FROM (r.rn = 1);
  -- counts shown on the storefront
  UPDATE public.taxonomy_nodes n SET product_count = (SELECT count(*) FROM public.product_taxonomy_links l WHERE l.node_id = n.id)
   WHERE n.tenant_id = p_tenant AND (p_node IS NULL OR n.id = p_node);
  RETURN jsonb_build_object('nodes', nodes, 'added', added, 'removed', removed, 'unchanged', kept);
END $$;

-- convenience RPC for the admin UI: map one source category (or path, or product) onto a listing category
CREATE OR REPLACE FUNCTION public.listing_map_category(p_tenant uuid, p_node uuid, p_source_category uuid DEFAULT NULL,
  p_source_path text DEFAULT NULL, p_supplier uuid DEFAULT NULL, p_product uuid DEFAULT NULL, p_rule jsonb DEFAULT NULL,
  p_effect text DEFAULT 'include', p_include_descendants boolean DEFAULT true, p_priority integer DEFAULT 100,
  p_is_primary boolean DEFAULT false, p_publish boolean DEFAULT true)
RETURNS public.listing_category_map LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog AS $$
DECLARE m public.listing_category_map; k text;
BEGIN
  IF NOT (public.platform__is_service() OR public.platform_has_role(p_tenant, 'manager')
          OR public.platform_has_permission(p_tenant, 'catalog.publish')) THEN
    RAISE EXCEPTION 'not allowed to change listing maps for this tenant' USING ERRCODE = 'insufficient_privilege';
  END IF;
  k := CASE WHEN p_product IS NOT NULL THEN 'product' WHEN p_source_category IS NOT NULL THEN 'source_category'
            WHEN p_source_path IS NOT NULL THEN 'source_path' WHEN p_rule IS NOT NULL THEN 'rule' END;
  IF k IS NULL THEN RAISE EXCEPTION 'say what to map: a source category, a source path, a product or a rule'; END IF;
  INSERT INTO public.listing_category_map(tenant_id, node_id, match_kind, source_category_id, supplier_id, source_path_prefix,
                                          catalog_product_id, rule, effect, include_descendants, priority, is_primary, created_by)
  VALUES (p_tenant, p_node, k, p_source_category, p_supplier, public.catalog__norm_path(p_source_path), p_product,
          coalesce(p_rule, '{}'::jsonb), p_effect, p_include_descendants, p_priority, p_is_primary, auth.uid())
  ON CONFLICT (tenant_id, node_id, match_kind, effect,
               coalesce(source_category_id, '00000000-0000-0000-0000-000000000000'::uuid),
               coalesce(supplier_id, '00000000-0000-0000-0000-000000000000'::uuid),
               coalesce(source_path_prefix, ''), coalesce(catalog_product_id, '00000000-0000-0000-0000-000000000000'::uuid), rule)
  DO UPDATE SET status = 'active', priority = EXCLUDED.priority, is_primary = EXCLUDED.is_primary,
                include_descendants = EXCLUDED.include_descendants, updated_at = now()
  RETURNING * INTO m;
  IF p_publish THEN PERFORM public.listing_publish(p_tenant, p_node); END IF;
  RETURN m;
END $$;

CREATE OR REPLACE FUNCTION public.listing_unmap(p_map uuid, p_publish boolean DEFAULT true)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog AS $$
DECLARE m public.listing_category_map;
BEGIN
  SELECT * INTO m FROM public.listing_category_map WHERE id = p_map;
  IF m.id IS NULL THEN RAISE EXCEPTION 'unknown map row'; END IF;
  IF NOT (public.platform__is_service() OR public.platform_has_role(m.tenant_id, 'manager')
          OR public.platform_has_permission(m.tenant_id, 'catalog.publish')) THEN
    RAISE EXCEPTION 'not allowed to change listing maps for this tenant' USING ERRCODE = 'insufficient_privilege';
  END IF;
  DELETE FROM public.listing_category_map WHERE id = p_map;
  IF p_publish THEN RETURN public.listing_publish(m.tenant_id, m.node_id); END IF;
  RETURN jsonb_build_object('nodes', 0);
END $$;

-- gap report: source categories with products that this tenant has not mapped anywhere
CREATE OR REPLACE FUNCTION public.listing_unmapped(p_tenant uuid, p_supplier uuid DEFAULT NULL)
RETURNS TABLE(supplier_id uuid, supplier_name text, source_category_id uuid, source_path text, products bigint, listed bigint)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_catalog AS $$
  SELECT s.id, s.name, c.id, c.path, count(p.id),
         count(p.id) FILTER (WHERE EXISTS (SELECT 1 FROM public.product_taxonomy_links l WHERE l.tenant_id = p_tenant AND l.product_id = p.id))
    FROM public.catalog_source_categories c
    JOIN public.suppliers s ON s.id = c.supplier_id
    JOIN public.supplier_catalog_products p ON p.source_category_id = c.id AND NOT p.is_hidden
   WHERE (public.platform__is_service() OR public.platform_is_tenant_member(p_tenant))
     AND (p_supplier IS NULL OR c.supplier_id = p_supplier)
   GROUP BY s.id, s.name, c.id, c.path
  HAVING count(p.id) FILTER (WHERE EXISTS (SELECT 1 FROM public.product_taxonomy_links l WHERE l.tenant_id = p_tenant AND l.product_id = p.id)) < count(p.id)
   ORDER BY count(p.id) DESC $$;

-- storefront read, tenant-aware (the legacy taxonomy_link_products(path, ...) has no tenant filter)
CREATE OR REPLACE FUNCTION public.listing_products(p_tenant uuid, p_path text, p_limit integer DEFAULT 48, p_offset integer DEFAULT 0)
RETURNS SETOF public.supplier_catalog_products LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_catalog AS $$
  SELECT p.*
    FROM public.product_taxonomy_links l
    JOIN public.taxonomy_nodes n ON n.id = l.node_id AND n.tenant_id = p_tenant AND n.status = 'published'
    JOIN public.supplier_catalog_products p ON p.id = l.product_id AND NOT p.is_hidden
   WHERE l.tenant_id = p_tenant AND l.path = p_path
   ORDER BY l.sort_order, p.created_at DESC
   LIMIT least(coalesce(p_limit, 48), 200) OFFSET greatest(coalesce(p_offset, 0), 0) $$;

-- fixed: counted products.category_id = taxonomy_nodes.id AND status = 'live' (wrong tree, a status that does not exist)
CREATE OR REPLACE FUNCTION public.recompute_category_counts() RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_catalog AS $$
  UPDATE public.taxonomy_nodes n
     SET product_count = (SELECT count(*) FROM public.product_taxonomy_links l
                            JOIN public.supplier_catalog_products p ON p.id = l.product_id AND NOT p.is_hidden
                           WHERE l.node_id = n.id)
   WHERE n.product_count IS DISTINCT FROM (SELECT count(*) FROM public.product_taxonomy_links l
                            JOIN public.supplier_catalog_products p ON p.id = l.product_id AND NOT p.is_hidden
                           WHERE l.node_id = n.id) $$;

-- =====================================================================
-- E. Move the old text mapping and legacy pins onto the map
-- =====================================================================
DO $$
DECLARE r record; sup uuid; src uuid; ten uuid; nd uuid; cat text; first boolean; n_src int := 0; n_map int := 0; n_miss int := 0; n_pin int := 0;
BEGIN
  SELECT id INTO ten FROM public.tenants WHERE slug = 'unsaid';
  FOR r IN SELECT * FROM public.supplier_category_mapping LOOP
    SELECT id INTO sup FROM public.suppliers WHERE lower(slug) = lower(r.supplier) OR lower(name) = lower(r.supplier) LIMIT 1;
    IF sup IS NULL THEN
      n_miss := n_miss + 1;
      PERFORM unify.log('06f', 'supplier_category_mapping', 'unknown_supplier', r.supplier || ' / ' || r.supplier_product_type);
      CONTINUE;
    END IF;
    src := public.catalog_upsert_source_category(sup, r.supplier_product_type, NULL,
             jsonb_build_object('lookup_key', r.lookup_key, 'from', 'supplier_category_mapping'));
    n_src := n_src + 1;
    UPDATE public.supplier_catalog_products SET source_product_type = coalesce(source_product_type, r.supplier_product_type),
           source_category_path = coalesce(source_category_path, public.catalog__norm_path(r.supplier_product_type))
     WHERE supplier_id = sup AND lower(source_product_type) = lower(r.supplier_product_type) AND source_category_id IS NULL;
    IF ten IS NULL THEN CONTINUE; END IF;
    first := true;
    FOREACH cat IN ARRAY (ARRAY[r.primary_category] || coalesce(r.categories, '{}'::text[])) LOOP
      CONTINUE WHEN cat IS NULL OR btrim(cat) = '';
      SELECT id INTO nd FROM public.taxonomy_nodes
       WHERE tenant_id = ten AND (path = btrim(cat) OR slug = btrim(cat) OR lower(name) = lower(btrim(cat)))
       ORDER BY (path = btrim(cat)) DESC, depth DESC LIMIT 1;
      IF nd IS NULL THEN
        n_miss := n_miss + 1;
        PERFORM unify.log('06f', 'supplier_category_mapping', 'unknown_listing_category', r.supplier || ' / ' || r.supplier_product_type || ' -> ' || cat);
      ELSE
        INSERT INTO public.listing_category_map(tenant_id, node_id, match_kind, source_category_id, is_primary, priority, notes)
        VALUES (ten, nd, 'source_category', src, first, CASE WHEN first THEN 10 ELSE 100 END, 'migrated from supplier_category_mapping')
        ON CONFLICT DO NOTHING;
        n_map := n_map + 1;
      END IF;
      first := false;
    END LOOP;
  END LOOP;
  -- supplier_catalog_products.category_id (global row -> tenant categories row) becomes a product pin for that tenant
  INSERT INTO public.listing_category_map(tenant_id, node_id, match_kind, catalog_product_id, is_primary, priority, notes)
  SELECT c.tenant_id, c.listing_node_id, 'product', p.id, true, 5, 'migrated from supplier_catalog_products.category_id'
    FROM public.supplier_catalog_products p JOIN public.categories c ON c.id = p.category_id
   WHERE c.listing_node_id IS NOT NULL
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS n_pin = ROW_COUNT;
  IF n_src + n_map + n_miss + n_pin > 0 THEN
    PERFORM unify.log('06f', 'listing_category_map', 'migrated',
      format('%s source categories, %s map rows, %s product pins, %s unmatched (see unify.run_log)', n_src, n_map, n_pin, n_miss));
  END IF;
END $$;
COMMENT ON TABLE public.supplier_category_mapping IS
  'LEGACY text mapping (supplier product type -> Unsaid category names). 06f moved it to catalog_source_categories + listing_category_map; read-only reference now.';
COMMENT ON TABLE public.erp_product_categories IS
  'Internal ERP classification (accounting / purchasing / reporting). Not a storefront listing; listings live in taxonomy_nodes.';
COMMENT ON TABLE public.categories IS
  'LEGACY second category tree. Each row is bridged to a listing node via listing_node_id; new listing work uses taxonomy_nodes.';

-- =====================================================================
-- F. Inventory stays separate: availability per listed product, no categories
-- =====================================================================
CREATE OR REPLACE VIEW public.listing_v_availability WITH (security_invoker = true) AS
SELECT l.tenant_id, l.node_id, l.path, l.product_id AS catalog_product_id, v.id AS catalog_variant_id,
       s.kind AS supplier_kind, sk.id AS sku_id, sk.sku,
       CASE WHEN sk.id IS NOT NULL THEN 'stocked'
            WHEN s.kind = 'pod' THEN 'made_to_order'
            ELSE 'supplier_stock' END AS availability_source,
       CASE WHEN sk.id IS NOT NULL THEN coalesce(b.available, 0) END AS available_qty,
       CASE WHEN sk.id IS NOT NULL THEN coalesce(b.available, 0) > 0 ELSE s.ordering_status <> 'catalog_only' END AS can_sell
  FROM public.product_taxonomy_links l
  JOIN public.supplier_catalog_products p ON p.id = l.product_id
  JOIN public.suppliers s ON s.id = p.supplier_id
  LEFT JOIN public.supplier_catalog_variants v ON v.supplier_catalog_product_id = p.id
  LEFT JOIN public.supplier_product_mappings spm ON spm.tenant_id = l.tenant_id AND spm.supplier_catalog_variant_id = v.id
  LEFT JOIN public.erp_product_skus sk ON sk.tenant_id = l.tenant_id AND sk.sku = spm.product_sku AND sk.is_active
  LEFT JOIN LATERAL (SELECT sum(ib.on_hand - ib.reserved - ib.allocated) AS available
                       FROM public.erp_inventory_balances ib
                      WHERE ib.tenant_id = l.tenant_id AND ib.sku_id = sk.id) b ON true;
COMMENT ON VIEW public.listing_v_availability IS
  'Inventory layer read: can a listed catalog product sell now. Local SKUs use stock balances; POD is made to order; dropship uses the supplier.';

-- =====================================================================
-- G. Module wiring, nav, security
-- =====================================================================
UPDATE public.platform_modules
   SET tables = tables || ARRAY(SELECT t FROM unnest(ARRAY['catalog_source_categories','listing_category_map','taxonomy_nodes','product_taxonomy_links']) t
                                 WHERE NOT (t = ANY (tables))),
       updated_at = now()
 WHERE code = 'products';

-- tenant tables: members read; managers (or catalog.publish) write through the RPCs or directly
ALTER TABLE public.listing_category_map ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS unify_tenant_rw ON public.listing_category_map;
CREATE POLICY unify_tenant_rw ON public.listing_category_map FOR ALL TO authenticated
  USING (public.platform_is_tenant_member(tenant_id))
  WITH CHECK (public.platform_has_role(tenant_id, 'manager') OR public.platform_has_permission(tenant_id, 'catalog.publish'));
-- the global catalog is written only by ingest (service role); everyone signed in may read it
REVOKE INSERT, UPDATE, DELETE ON public.catalog_source_categories FROM authenticated, anon;
INSERT INTO public.platform_table_access_overrides(table_name, access_mode, notes)
SELECT 'catalog_source_categories', 'global_read', 'unify 06f: global product catalog (source categories, names intact)'
 WHERE NOT EXISTS (SELECT 1 FROM public.platform_table_access_overrides o WHERE o.table_name = 'catalog_source_categories');

DO $$
DECLARE f text;
BEGIN
  FOREACH f IN ARRAY ARRAY['listing_publish','listing_map_category','listing_unmap','listing_unmapped','listing_products'] LOOP
    EXECUTE (SELECT string_agg(format('REVOKE EXECUTE ON FUNCTION %s FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION %s TO authenticated, service_role',
                                      p.oid::regprocedure, p.oid::regprocedure), '; ')
               FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = f);
  END LOOP;
  -- storefronts read without a login
  EXECUTE (SELECT string_agg(format('GRANT EXECUTE ON FUNCTION %s TO anon', p.oid::regprocedure), '; ')
             FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = 'listing_products');
  FOREACH f IN ARRAY ARRAY['catalog_upsert_source_category','catalog__product_source_category','listing__link_guard',
     'listing__node_path_moved','listing__map_matches','recompute_category_counts'] LOOP
    EXECUTE (SELECT string_agg(format('REVOKE EXECUTE ON FUNCTION %s FROM PUBLIC, anon, authenticated', p.oid::regprocedure), '; ')
               FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = f);
  END LOOP;
END $$;

-- (deferred: platform__apply_app_security() runs once at the end of the baseline,
--  after 61_policies, so explicit CREATE POLICY app_* statements land first.)

-- ---------------------------------------------------------------------
-- 29. Create Actions/07_actions_and_nav (1).sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- 07_actions_and_nav.sql — wire the UI spec to the canonical schema.
--
--   1. Dashboards & widgets + KPI targets tables (the only nav items that
--      had no backing table).
--   2. platform_quick_action_registry: every Create action, Standard action
--      and option-menu action in the spec, bound to a canonical RPC (rpc),
--      an RLS-protected table (table), a pure screen (ui) or an outside
--      provider (integration). Legacy writers (create_bill,
--      create_purchase_order, create_sales_order, create_receipt) are
--      never bound.
--   3. platform_feature_tree_coverage: every nav path in the spec, including
--      the four "Not Defined" areas (Payroll, Time, Inventory, Sales Tax),
--      with its backing table. is_implemented is true only when that table
--      or view exists.
--   4. pg_cron jobs (if pg_cron is installed): unify.reconcile() every 10
--      minutes; support_run_clocks() and platform_dispatch_reminders()
--      every minute (from 06b).
-- Idempotent: upserts on action_code / feature_path.
-- =====================================================================
\set ON_ERROR_STOP on
BEGIN;

-- ---------------------------------------------------------------------
-- 1. Dashboards, widgets, KPI targets
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.platform_dashboards (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  name          text NOT NULL,
  module        text NOT NULL DEFAULT 'home',      -- home, finance, orders, support ...
  owner_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  is_default    boolean NOT NULL DEFAULT false,
  is_shared     boolean NOT NULL DEFAULT true,
  layout        jsonb NOT NULL DEFAULT '[]'::jsonb,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, module, name)
);
CREATE TABLE IF NOT EXISTS public.platform_dashboard_widgets (
  id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id            uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  dashboard_id         uuid NOT NULL REFERENCES public.platform_dashboards(id) ON DELETE CASCADE,
  report_definition_id uuid REFERENCES public.platform_report_definitions(id) ON DELETE SET NULL,
  widget_type          text NOT NULL CHECK (widget_type IN ('kpi','line','bar','pie','table','list','funnel','map','text')),
  title                text NOT NULL,
  metric_code          text,                    -- e.g. gmv, orders, aov, open_tickets, sla_breaches
  config               jsonb NOT NULL DEFAULT '{}'::jsonb,
  position             jsonb NOT NULL DEFAULT '{}'::jsonb,   -- {x,y,w,h}
  sort_order           integer NOT NULL DEFAULT 100,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS platform_dashboard_widgets_dash_idx ON public.platform_dashboard_widgets(dashboard_id);
CREATE TABLE IF NOT EXISTS public.platform_kpi_targets (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id    uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  metric_code  text NOT NULL,
  period_type  text NOT NULL DEFAULT 'month' CHECK (period_type IN ('day','week','month','quarter','year')),
  period_start date NOT NULL,
  target_value numeric NOT NULL,
  owner_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  notes        text,
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, metric_code, period_type, period_start)
);

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['platform_dashboards','platform_dashboard_widgets','platform_kpi_targets'] LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('DROP POLICY IF EXISTS unify_tenant_rw ON public.%I', t);
    EXECUTE format('CREATE POLICY unify_tenant_rw ON public.%I FOR ALL TO authenticated
                      USING (public.platform_is_tenant_member(tenant_id)) WITH CHECK (public.platform_is_tenant_member(tenant_id))', t);
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
  END LOOP;
END $$;

-- ---------------------------------------------------------------------
-- 2. Quick action registry
--    line: code | module | area | object_type | kind | impl | binding | display name | access
--    impl rpc -> binding is the function; table -> binding is the table;
--    ui / integration -> binding is the screen route (stored in ui_route).
-- ---------------------------------------------------------------------
CREATE TEMP TABLE _qa(code text, module text, area text, object_type text, kind text, impl text,
                      binding text, display text, access text, ord int) ON COMMIT DROP;
INSERT INTO _qa
SELECT trim(f[1]), trim(f[2]), trim(f[3]), trim(f[4]), trim(f[5]), trim(f[6]), trim(f[7]), trim(f[8]),
       coalesce(nullif(trim(f[9]), ''), 'member'), (row_number() OVER ()) * 10
  FROM (SELECT string_to_array(l, '|') f
          FROM regexp_split_to_table($QA$
